document.addEventListener('DOMContentLoaded', () => {
    setupEventListeners();
    try {
        initCourse();
    } catch (e) {
        console.error("Error initializing course:", e);
    }
});

let currentLessonId = null;

function setupEventListeners() {
    // Mobile Sidebar Toggle Logic
    const toggleBtn = document.getElementById('mobile-sidebar-toggle');
    const closeBtn = document.getElementById('close-sidebar-mobile');
    const sidebar = document.getElementById('sidebar');

    if (toggleBtn && sidebar) {
        toggleBtn.addEventListener('click', (e) => {
            e.preventDefault(); // Prevent default behavior
            e.stopPropagation(); // Stop propagation just in case
            console.log("Toggle button clicked"); // Debug log for user
            sidebar.classList.add('open');
        });
    } else {
        console.error("Toggle button or sidebar not found in DOM");
    }

    if (closeBtn && sidebar) {
        closeBtn.addEventListener('click', () => {
            sidebar.classList.remove('open');
        });
    }
}

function initCourse() {
    const course = courseData.data;

    // Set Course Info
    document.getElementById('course-name').textContent = course.name;
    document.getElementById('course-description').innerHTML = course.description;

    // Render Sidebar
    renderSidebar(course.courseChapters.data);

    // Auto play first lesson of first chapter if available
    const firstChapter = course.courseChapters.data[0];
    if (firstChapter && firstChapter.lessons.data.length > 0) {
        const firstLesson = firstChapter.lessons.data[0];
        playLesson(firstLesson);

        // Open the first chapter in sidebar
        const firstChapterHeader = document.querySelector(`.chapter-header[data-chapter-id="${firstChapter.id}"]`);
        if (firstChapterHeader) {
            toggleChapter(firstChapterHeader);
        }
    }
}

function renderSidebar(chapters) {
    const sidebarContent = document.getElementById('sidebar-content');

    chapters.forEach((chapter, index) => {
        const chapterDiv = document.createElement('div');
        chapterDiv.className = 'chapter-item';

        const header = document.createElement('div');
        header.className = 'chapter-header';
        header.setAttribute('data-chapter-id', chapter.id);
        header.onclick = () => toggleChapter(header);
        header.innerHTML = `
            <span>${index + 1}. ${chapter.name}</span>
            <i class="fas fa-chevron-down"></i>
        `;

        const lessonsContainer = document.createElement('div');
        lessonsContainer.className = 'chapter-lessons';
        lessonsContainer.id = `chapter-${chapter.id}`;

        chapter.lessons.data.forEach((lesson, lessonIndex) => {
            const lessonItem = document.createElement('div');
            lessonItem.className = 'lesson-item';
            lessonItem.setAttribute('data-lesson-id', lesson.id);
            lessonItem.onclick = () => {
                playLesson(lesson);
                // Close sidebar on mobile after selection
                if (window.innerWidth <= 900) {
                    document.getElementById('sidebar').classList.remove('open');
                }
            };
            lessonItem.innerHTML = `
                <div class="lesson-icon"><i class="fas fa-play-circle"></i></div>
                <span>${lesson.name}</span>
            `;
            lessonsContainer.appendChild(lessonItem);
        });

        chapterDiv.appendChild(header);
        chapterDiv.appendChild(lessonsContainer);
        sidebarContent.appendChild(chapterDiv);
    });
}

function toggleChapter(headerElement) {
    // Toggle active state for style
    headerElement.classList.toggle('active');

    // Find the next sibling which is the lessons container
    const content = headerElement.nextElementSibling;
    content.classList.toggle('open');

    // Rotate icon
    const icon = headerElement.querySelector('i');
    if (content.classList.contains('open')) {
        icon.className = 'fas fa-chevron-up';
    } else {
        icon.className = 'fas fa-chevron-down';
    }
}

function playLesson(lesson) {
    currentLessonId = lesson.id;

    // Update Video
    const iframe = document.getElementById('video-frame');
    iframe.src = `https://iframe.videodelivery.net/${lesson.link}`;

    // Update Info
    document.getElementById('lesson-title').textContent = lesson.name;

    // Update UI Active State
    document.querySelectorAll('.lesson-item').forEach(item => {
        item.classList.remove('active');
        if (parseInt(item.getAttribute('data-lesson-id')) === lesson.id) {
            item.classList.add('active');

            // Ensure parent chapter is open
            const chapterContent = item.parentElement;
            if (!chapterContent.classList.contains('open')) {
                const header = chapterContent.previousElementSibling;
                toggleChapter(header);
            }
        }
    });
}
